class Result:
    def __init__(self, value=None, error=None):
        self.value = value
        self.error = error

    def is_ok(self):
        return self.error is None

    @staticmethod
    def ok(value):
        return Result(value=value)

    @staticmethod
    def err(error):
        return Result(error=error)

    def map(self, func):
        if self.is_ok():
            return func(self.value)
        else:
            return self

    def and_then(self, func):
        if self.is_ok():
            return func(self.value)
        else:
            return self

    @staticmethod
    def collect(results):
        errors = [r.error for r in results if not r.is_ok()]
        if errors:
            return Result.err("\n".join(errors))
        else:
            return Result.ok([r.value for r in results if r.is_ok()])

def get_sym_json_path(args, region_json) -> Result:
    def get_path(region) -> Result:
        upper_region = region.upper()
        if upper_region in region_json['_Regions_']:
            return Result.ok(region_json['_Regions_'][upper_region])
        else:
            return Result.err(f"{region} not found in _Regions_")

    results = [get_path(region) for region in args['region']]
    return Result.collect(results)

