To allow administrators to choose which photo to keep when duplicates are submitted, we need to modify the backend to handle duplicate submissions by storing them temporarily and providing an endpoint for administrators to resolve duplicates. Additionally, we'll update the frontend to provide user feedback when an upload is rejected due to a duplicate entry.

### Backend Implementation

We'll modify the backend to handle duplicate submissions by storing them temporarily and providing an endpoint for administrators to resolve duplicates.

```python
from flask import Flask, request, jsonify
import os
from werkzeug.utils import secure_filename
import sqlite3

app = Flask(__name__)

# Database setup
def init_db():
    conn = sqlite3.connect('photos.db')
    c = conn.cursor()
    c.execute('''CREATE TABLE IF NOT EXISTS photos
                 (id INTEGER PRIMARY KEY, name TEXT, price REAL, description TEXT, filename TEXT)''')
    c.execute('''CREATE TABLE IF NOT EXISTS pending_photos
                 (id INTEGER PRIMARY KEY, name TEXT, price REAL, description TEXT, filename TEXT)''')
    conn.commit()
    conn.close()

@app.route('/upload', methods=['POST'])
def upload_file():
    if 'file' not in request.files:
        return "No file part", 400
    file = request.files['file']
    if file.filename == '':
        return "No selected file", 400
    if file:
        filename = secure_filename(file.filename)
        file.save(os.path.join("uploads/", filename))

        # Extract other form data
        name = request.form.get('name')
        price = float(request.form.get('price'))
        description = request.form.get('description')

        # Check for duplicate names
        conn = sqlite3.connect('photos.db')
        c = conn.cursor()
        c.execute("SELECT * FROM photos WHERE name=?", (name,))
        existing_photo = c.fetchone()

        if existing_photo:
            # Store duplicate photo in pending table
            c.execute("INSERT INTO pending_photos (name, price, description, filename) VALUES (?, ?, ?, ?)",
                      (name, price, description, filename))
            conn.commit()
            conn.close()
            return f"Duplicate name {name}, please contact admin to resolve.", 409

        # Insert new photo details into database
        c.execute("INSERT INTO photos (name, price, description, filename) VALUES (?, ?, ?, ?)",
                  (name, price, description, filename))
        conn.commit()
        conn.close()

        return "File uploaded successfully", 200

@app.route('/admin/resolve_duplicate', methods=['POST'])
def resolve_duplicate():
    photo_id = request.form.get('id')
    action = request.form.get('action')  # 'keep' or 'replace'
    conn = sqlite3.connect('photos.db')
    c = conn.cursor()
    c.execute("SELECT * FROM pending_photos WHERE id=?", (photo_id,))
    pending_photo = c.fetchone()

    if pending_photo:
        if action == 'keep':
            c.execute("DELETE FROM photos WHERE name=?", (pending_photo[1],))
            c.execute("INSERT INTO photos (name, price, description, filename) VALUES (?, ?, ?, ?)",
                      (pending_photo[1], pending_photo[2], pending_photo[3], pending_photo[4]))
        elif action == 'replace':
            c.execute("DELETE FROM pending_photos WHERE id=?", (photo_id,))
    conn.commit()
    conn.close()
    return "Resolved", 200

@app.route('/admin/duplicates', methods=['GET'])
def list_pending_photos():
    conn = sqlite3.connect('photos.db')
    c = conn.cursor()
    c.execute("SELECT * FROM pending_photos")
    results = c.fetchall()
    conn.close()

    # Format results for JSON response
    formatted_results = [{"id": r[0], "name": r[1], "price": r[2], "description": r[3], "filename": r[4]} for r in results]
    return jsonify(formatted_results)

if __name__ == '__main__':
    init_db()
    app.run(debug=True)
```

### Explanation

- **Pending Photos Table**: We added a `pending_photos` table to store duplicate submissions temporarily.
- **Duplicate Handling**: When a duplicate submission is detected, it is stored in the `pending_photos` table and the user is notified to contact an administrator.
- **Resolve Duplicate Endpoint**: The `/admin/resolve_duplicate` endpoint allows administrators to either keep or replace the existing photo with the duplicate. If they choose to keep it, the existing photo is deleted and the new photo is added to the `photos` table.
- **List Pending Photos**: The `/admin/duplicates` endpoint lists pending duplicates for the admin to choose from.

